    colors=[x[2] for x in sorted(legends)]
    objects=components({5}); n=len(objects); k=len(colors)
    areas=sorted(len(x) for x in objects)
    # Optimal one-dimensional k-means: consecutive clusters of sorted areas.
    pref=[0]
    for x in areas: pref.append(pref[-1]+x)
    def cost(i,j):
        s=pref[j]-pref[i]; return sum(areas[t]**2 for t in range(i,j))-s*s/(j-i)
    inf=float('inf'); dp=[[inf]*(n+1) for _ in range(k+1)]; prev=[[None]*(n+1) for _ in range(k+1)]; dp[0][0]=0
    for q in range(1,k+1):
        for j in range(q,n+1):
            for i in range(q-1,j):
                v=dp[q-1][i]+cost(i,j)
                if v<dp[q][j]: dp[q][j]=v; prev[q][j]=i
    cuts=[]; j=n
    for q in range(k,0,-1):
        i=prev[q][j]; cuts.append((areas[i],areas[j-1])); j=i
    cuts=cuts[::-1]
    for obj in objects:
        a=len(obj); idx=next(q for q,(lo,hi) in enumerate(cuts) if lo<=a<=hi)
        for r,c in obj: g[r][c]=colors[idx]
    return g
